import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {pathToFileURL} from 'node:url';
import {spawnSync} from 'node:child_process';

// Run real game logic with a small DOM/canvas stand-in. Browser rendering is
// checked separately; these tests exercise the mission and combat rules.
const gradient={addColorStop(){}};
const context=new Proxy({createLinearGradient:()=>gradient,createRadialGradient:()=>gradient,measureText:t=>({width:t.length*8}),createImageData:(w,h)=>({width:w,height:h,data:new Uint8ClampedArray(w*h*4)})}, {get:(t,k)=>k in t?t[k]:(...args)=>{},set:(t,k,v)=>(t[k]=v,true)});
const elements=new Map();
const eventListeners=new WeakMap();
function listen(target,type,handler){if(!eventListeners.has(target))eventListeners.set(target,new Map());const listeners=eventListeners.get(target);if(!listeners.has(type))listeners.set(type,[]);listeners.get(type).push(handler);}
function dispatch(target,type,event={}){for(const handler of eventListeners.get(target)?.get(type)||[])handler({type,preventDefault(){},...event});}
function element(id=''){if(elements.has(id))return elements.get(id);const classes=new Set();const e={id,width:600,height:600,value:'survivor',style:{},attributes:{},classList:{add:x=>classes.add(x),remove:x=>classes.delete(x),toggle:(x,v)=>v?classes.add(x):classes.delete(x),contains:x=>classes.has(x)},textContent:'',innerHTML:'',getContext:()=>context,append(){},remove(){},addEventListener(type,handler){listen(this,type,handler);},querySelector:s=>element(id+s),querySelectorAll:()=>[],focus(){},requestPointerLock:()=>Promise.resolve(),requestFullscreen:()=>Promise.resolve(),setAttribute(name,value){this.attributes[name]=String(value);},getAttribute(name){return this.attributes[name];}};elements.set(id,e);return e;}
globalThis.document={getElementById:element,createElement:t=>element(t+Math.random()),addEventListener(type,handler){listen(this,type,handler);},documentElement:element('html'),fullscreenElement:null,fullscreenEnabled:true,exitFullscreen:()=>Promise.resolve(),pointerLockElement:null,exitPointerLock(){},hidden:false};
globalThis.window={addEventListener(type,handler){listen(this,type,handler);}};globalThis.matchMedia=()=>({matches:false});globalThis.innerWidth=1280;globalThis.innerHeight=720;
const storage=new Map();globalThis.localStorage={getItem:k=>storage.get(k)||null,setItem:(k,v)=>storage.set(k,v)};
const realTimeout=globalThis.setTimeout;globalThis.setTimeout=()=>0;
let code=fs.readFileSync('dist/game.js','utf8').replace(/from\s+(['"])(\.\/[^'"]+)\1/g,(_match,_quote,specifier)=>'from '+JSON.stringify(pathToFileURL(path.resolve('dist',specifier)).href)).replace(/\ninit\(\);\s*$/,'');
code+=`\nexport {createWorld,makeNav,findPath,isClear,lineClear,resetRun,initialState,readSave,save,pause,interactables,enemies,colliders,spawns,player,shoot,reload,finishReload,switchWeapon,heal,hurt,interact,closePanel,showEnding,begin,createEnemy,damageEnemy,updateEnemies,weapons,updatePlayer,safeRestore,drink,updateSurvival,collectSupply,collectRobotGold,acceptQuest,claimQuest,claimWelcome,questReady,pickups,quests,allies,mats,claimPumpWater,buyFromGreenline,updateAllies,platforms,worldBuildings,climbRoutes,settlements,extraSpawns,EXPANSION_LIMIT,perkBonuses,awardXP,unlockPerk,canUnlockSkill,SKILL_NODES,supportAt,updateVertical,beginClimb,updateClimb,updateInteract,claimSettlementWater,lootInterior,updateEffects,projectiles,enemyFire,nextLevelXP,lockMouse,unlockMouse,handlePointerLockChange,updateMouseCaptureUI,onPointerLockError,toggleFullscreen,updateFullscreenUI,bindInput,bench,handleDesktopCapture,handleDesktopMove};
export const inspect=()=>({state,mode,scene,camera,gun,shootTimer,reloadTimer,interactTarget,climbState,velocityY,fireHeld,aiming,keys,yaw,pitch,hadPointerLock,pointerPending,pointerAvailable,intentionalUnlock,mouseCaptureWanted});
export const configure=(v)=>{if(v.state)state=v.state;if(v.mode)mode=v.mode;if(Object.hasOwn(v,'target'))interactTarget=v.target;if(v.yaw!==undefined)yaw=v.yaw;if(v.pitch!==undefined)pitch=v.pitch;if(v.keys)keys=v.keys;if(v.velocityY!==undefined)velocityY=v.velocityY;shootTimer=0;invulnerable=v.invulnerable??0;};
`;
fs.writeFileSync('test-runtime.mjs',code);
const game=await import('./test-runtime.mjs?'+Date.now());
let passed=0;
const failures=[];
function test(name,fn){try{fn();passed++;console.log('PASS '+name);}catch(error){failures.push({name,error});console.error('FAIL '+name+'\n'+error.message);}}
async function testAsync(name,fn){try{await fn();passed++;console.log('PASS '+name);}catch(error){failures.push({name,error});console.error('FAIL '+name+'\n'+error.message);}}
const near=(a,b,epsilon=1e-5)=>Math.abs(a-b)<=epsilon;
const distance2=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
function placeAt(point){game.player.x=point.x;game.player.z=point.z;game.player.y=(point.y||0)+1.72;game.configure({mode:'playing',keys:{},velocityY:0,target:null});}
function walkTo(point){const dx=point.x-game.player.x,dz=point.z-game.player.z,d=Math.hypot(dx,dz);game.configure({mode:'playing',yaw:Math.atan2(-dx,-dz),keys:{KeyW:true},velocityY:0});let left=d/4.6;while(left>1e-8){const dt=Math.min(.02,left);game.updatePlayer(dt);left-=dt;}game.configure({keys:{}});}
function finishClimb(){for(let n=0;n<1200&&game.inspect().climbState;n++)game.updateClimb(.05);assert.equal(game.inspect().climbState,null,'climb never completed');}
game.createWorld();game.makeNav();game.resetRun();game.configure({mode:'playing'});
test('Ground-level missions, caches, people and supplies are reachable',()=>{for(const item of game.interactables){if(item.wilderness||(item.y||0)>.5)continue;assert(game.isClear(item.x,item.z,.3,Math.max(0,item.y||0)),item.name+' is inside a collider');const p=game.findPath(0,65,item.x,item.z);assert(p.length>0,item.name+' has no path');}});
test('Original and outer-district enemy spawn points are navigable',()=>{for(const spawn of [...game.spawns,...game.extraSpawns]){const [x,z,type]=Array.isArray(spawn)?spawn:[spawn.x,spawn.z,spawn.type];assert(game.isClear(x,z,.55),`${type} at ${x},${z} is obstructed`);assert(game.findPath(x,z,0,65).length>0);}});
test('Buildings block visibility and movement; streets remain open',()=>{assert(!game.lineClear(20,55,40,55));assert(!game.isClear(31,58));assert(game.lineClear(0,64,0,35));const old={...game.player};game.player.x=18.5;game.player.z=58;game.configure({yaw:0,keys:{KeyD:true}});for(let i=0;i<50;i++)game.updatePlayer(.05);assert(game.player.x<20,'walked through building');Object.assign(game.player,old);game.configure({keys:{}});});
test('Reload transfers cartridges without creating ammo',()=>{const s=game.inspect().state;s.ammo[0]=2;s.reserve[0]=11;game.reload();assert(game.inspect().reloadTimer>0);game.finishReload();assert.equal(s.ammo[0],13);assert.equal(s.reserve[0],0);});
test('Locked weapons cannot be selected',()=>{game.switchWeapon(2);assert.equal(game.inspect().state.weapon,0);});
test('Loot grants weapon, supplies, and a persistent save only once',()=>{const cache=game.interactables.find(i=>i.type==='crate'&&i.reward===1);const s=game.inspect().state;game.configure({target:cache});game.interact();assert(s.unlocked[1]);assert.equal(s.weapon,1);assert.equal(s.opened.length,1);const after=JSON.stringify({scrap:s.scrap,gold:s.gold,water:s.water,meds:s.meds,ammo:s.ammo,reserve:s.reserve});game.interact();assert.equal(JSON.stringify({scrap:s.scrap,gold:s.gold,water:s.water,meds:s.meds,ammo:s.ammo,reserve:s.reserve}),after);assert.equal(game.readSave().weapon,1);});
test('Medkits respect capacity and cannot be spent at full health',()=>{const s=game.inspect().state;const before=s.meds;game.heal();assert.equal(s.meds,before);s.health=50;game.heal();assert.equal(s.health,100);assert.equal(s.meds,before-1);});
test('Armor absorbs part of a hit and health takes the remainder',()=>{const s=game.inspect().state;s.health=100;s.armor=40;game.configure({mode:'playing'});game.hurt(20);assert.equal(s.armor,27);assert.equal(s.health,93);});
test('A real raycast damages a target and consumes one cartridge',()=>{game.resetRun();game.configure({mode:'playing'});for(const e of [...game.enemies])game.damageEnemy(e,999,new (game.inspect().camera.position.constructor)(e.x,1,e.z));game.createEnemy(900,0,50,'walker');game.player.x=0;game.player.z=60;const {camera}=game.inspect();camera.position.set(0,1.4,60);camera.rotation.set(0,0,0);const e=game.enemies[0],hp=e.health;game.shoot();assert(e.health<hp);assert.equal(game.inspect().state.ammo[0],23);});
test('Real raycasts cannot shoot through a concrete building',()=>{const e=game.enemies[0];e.x=40;e.z=58;e.group.position.set(40,0,58);const {camera}=game.inspect();camera.position.set(18,1.4,58);camera.lookAt(40,1.4,58);const hp=e.health;game.configure({mode:'playing'});game.shoot();assert.equal(e.health,hp);});
test('Mission sequence rejects later cores and guarded stations',()=>{game.resetRun();game.configure({mode:'playing'});const cores=game.interactables.filter(i=>i.type==='core');game.configure({target:cores[2]});game.interact();assert.equal(game.inspect().state.cores.length,0);game.configure({target:cores[0]});game.interact();assert.equal(game.inspect().state.cores.length,0);});
test('All three story chapters complete, save, and restore',()=>{for(const e of [...game.enemies])game.damageEnemy(e,999,new (game.inspect().camera.position.constructor)(e.x,1,e.z));for(const core of game.interactables.filter(i=>i.type==='core')){game.configure({mode:'playing',target:core});game.interact();assert.equal(game.inspect().mode,'story');game.closePanel();assert.equal(game.inspect().state.cores.length,core.id+1);}const saved=game.readSave();assert.deepEqual(saved.cores,[0,1,2]);assert(saved.logs.includes(3));game.resetRun(saved);assert.deepEqual(game.inspect().state.cores,[0,1,2]);assert.equal(game.enemies.length,0);});
test('Both ending choices persist and retain exploration progress',()=>{for(const ending of ['garden','warning']){game.showEnding(ending);assert.equal(game.readSave().ending,ending);assert.equal(game.inspect().mode,'ending');assert.equal(game.inspect().state.cores.length,3);}});
test('Death preserves the last living checkpoint',()=>{game.configure({mode:'playing'});const s=game.inspect().state;s.ending=null;s.health=80;game.save();s.health=1;s.armor=0;game.hurt(100);assert.equal(game.inspect().mode,'dead');assert.equal(game.readSave().health,80);game.begin(game.readSave());assert.equal(game.inspect().state.health,80);});
test('A fresh story clears prior weapons, kills, cores, caches and survival progress',()=>{game.resetRun();const s=game.inspect().state;assert.deepEqual(s.cores,[]);assert.deepEqual(s.opened,[]);assert.deepEqual(s.killed,[]);assert.deepEqual(s.unlocked,[true,false,false,false,false,false]);assert.equal(game.enemies.length,game.spawns.length+game.extraSpawns.length);assert.equal(s.hydration,100);assert.equal(s.water,3);assert.equal(s.gold,0);assert.deepEqual(s.supplies,[]);assert.deepEqual(s.questItems,[]);assert.deepEqual(s.pendingGold,[]);});

test('Version-one saves migrate without losing story, loot, ammunition or upgrades',()=>{const legacy={version:1,difficulty:'desolate',health:61,armor:23,meds:2,scrap:74,weapon:2,unlocked:[true,true,true],ammo:[8,2,4],reserve:[91,17,22],cores:[0],opened:[0,2],logs:[0,1],killed:[0,1],damageLevel:1,armorLevel:2,kills:2,shots:90,hits:70,elapsed:318,ending:null,position:{x:-48,z:20},yaw:1.2,pitch:.1};storage.set('EARTHtotaled.story.v1',JSON.stringify(legacy));assert(game.readSave(),'the legacy storage key must remain readable');game.resetRun(game.readSave());const s=game.inspect().state;assert.equal(s.version,3);assert.equal(s.health,61);assert.equal(s.weapon,2);assert.equal(s.scrap,74);assert.equal(s.damageLevel,1);assert.equal(s.armorLevel,2);assert.deepEqual(s.cores,[0]);assert.deepEqual(s.opened,[0,2]);assert.deepEqual(s.killed,[0,1]);assert.deepEqual(s.ammo.slice(0,3),[8,2,4]);assert.deepEqual(s.reserve.slice(0,3),[91,17,22]);assert.deepEqual(s.unlocked,[true,true,true,false,false,false]);assert.equal(s.ammo.length,6);assert.equal(s.reserve.length,6);assert.equal(s.hydration,100);assert.equal(s.water,3);assert.equal(s.gold,0);assert.equal(game.player.x,-48);assert.equal(game.player.z,20);assert.deepEqual(s.skills,['survivor']);assert.equal(s.skillPoints,2);assert.equal(s.xp,0);assert.equal(s.level,1);assert.deepEqual(s.visitedBuildings,[]);assert.deepEqual(s.settlementRefills,{});});

test('Zero hydration and empty bottles survive save/restore exactly',()=>{game.resetRun();const s=game.inspect().state;s.hydration=0;s.water=0;s.health=42;game.save();game.resetRun(game.readSave());assert.equal(game.inspect().state.hydration,0);assert.equal(game.inspect().state.water,0);assert.equal(game.inspect().state.health,42);});

test('Hydration drains only during play and difficulty changes the rate',()=>{game.resetRun();const s=game.inspect().state;for(const mode of ['menu','paused','story','journal','map','bench','ending','choice','dead']){game.configure({mode,keys:{}});const h=s.hydration,hp=s.health;game.updateSurvival(10);assert.equal(s.hydration,h,mode+' drained water');assert.equal(s.health,hp,mode+' hurt the player');}game.configure({mode:'playing',keys:{}});s.difficulty='survivor';game.updateSurvival(10);assert(Math.abs(s.hydration-98.2)<1e-6);s.hydration=100;s.difficulty='wanderer';game.updateSurvival(10);assert(Math.abs(s.hydration-98.8)<1e-6);s.hydration=100;s.difficulty='desolate';game.updateSurvival(10);assert(Math.abs(s.hydration-97.5)<1e-6);s.difficulty='survivor';});

test('Sprinting consumes more water than walking',()=>{const s=game.inspect().state;s.hydration=100;game.configure({mode:'playing',keys:{KeyW:true}});game.updateSurvival(10);const walk=100-s.hydration;s.hydration=100;game.configure({keys:{KeyW:true,ShiftLeft:true}});game.updateSurvival(10);assert((100-s.hydration)>walk);assert(Math.abs((100-s.hydration)-walk*1.6)<1e-6);game.configure({keys:{}});});

test('Drinking consumes exactly one bottle and respects full/empty inventory',()=>{const s=game.inspect().state;game.configure({mode:'playing'});s.hydration=60;s.water=3;game.drink();assert.equal(s.hydration,100);assert.equal(s.water,2);game.drink();assert.equal(s.water,2);s.hydration=61;game.drink();assert.equal(s.water,2);s.hydration=0;s.water=0;game.drink();assert.equal(s.hydration,0);assert.equal(s.water,0);s.water=1;game.configure({mode:'paused'});game.drink();assert.equal(s.water,1);game.configure({mode:'playing'});game.drink();assert.equal(s.water,0);assert.equal(s.hydration,40);});

test('Dehydration bypasses armor and hit invulnerability, is lethal, and preserves a checkpoint',()=>{game.resetRun();game.configure({mode:'playing',keys:{},invulnerable:99});const s=game.inspect().state;s.hydration=0;s.water=0;s.health=10;s.armor=40;game.save();game.updateSurvival(1);assert.equal(s.health,8);assert.equal(s.armor,40);for(let i=0;i<4;i++)game.updateSurvival(1);assert.equal(s.health,0);assert.equal(game.inspect().mode,'dead');assert.equal(s.armor,40);assert.equal(game.readSave().health,10);});

test('Water supplies can be collected only once, including after reload',()=>{game.resetRun();game.configure({mode:'playing'});let s=game.inspect().state;const supply={id:'test-water-cache',type:'water',water:2,group:{visible:true}};game.collectSupply(supply);assert.equal(s.water,5);assert(s.supplies.includes(supply.id));game.collectSupply(supply);assert.equal(s.water,5);game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});s=game.inspect().state;game.collectSupply(supply);assert.equal(s.water,5);});

test('Every hostile robot type drops gold and never water',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.water=1;s.hydration=55;for(const type of ['walker','drone','heavy']){const enemy=game.enemies.find(e=>e.type===type);assert(enemy,'missing '+type);const amountBefore=s.gold;game.damageEnemy(enemy,999,new (game.inspect().camera.position.constructor)(enemy.x,1,enemy.z));const record=s.pendingGold.at(-1);assert(record?.gold>0,'missing robot gold record');const pickup=game.pickups.find(p=>p.id===record.id);assert(pickup,'missing collectible gold');assert(!pickup.water,'robot pickup contains water');game.collectRobotGold(pickup);assert.equal(s.gold,amountBefore+record.gold);assert.equal(s.water,1);assert.equal(s.hydration,55);const after=s.gold;game.collectRobotGold(pickup);assert.equal(s.gold,after,'gold was collected twice');}});

test('Uncollected robot gold persists while dead robots stay dead',()=>{game.resetRun();game.configure({mode:'playing'});const enemy=game.enemies[0];const id=enemy.id;game.damageEnemy(enemy,999,new (game.inspect().camera.position.constructor)(enemy.x,1,enemy.z));const goldRecord={...game.inspect().state.pendingGold[0]};game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});assert(!game.enemies.some(e=>e.id===id));assert.equal(game.inspect().state.pendingGold.length,1);const pickup=game.pickups.find(p=>p.id===goldRecord.id);assert(pickup,'pending gold did not reappear');game.collectRobotGold(pickup);assert.equal(game.inspect().state.gold,goldRecord.gold);assert.equal(game.inspect().state.pendingGold.length,0);game.save();game.resetRun(game.readSave());assert.equal(game.inspect().state.pendingGold.length,0);assert(!game.pickups.some(p=>p.id===goldRecord.id));});

test('Human welcome water cannot be claimed twice or farmed by reloading',()=>{game.resetRun();game.configure({mode:'playing'});game.claimWelcome();const s=game.inspect().state;assert.equal(s.welcomeClaimed,true);const water=s.water,gold=s.gold;game.claimWelcome();assert.equal(s.water,water);assert.equal(s.gold,gold);game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});game.claimWelcome();assert.equal(game.inspect().state.water,water);assert.equal(game.inspect().state.gold,gold);});

test('Human water quests require acceptance and the item, and reward once',()=>{for(const [id,bottles,gold] of [['filter',3,40],['pump',4,60]]){game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.water=0;s.gold=0;game.claimQuest(id);assert.equal(s.water,0);assert.equal(s.gold,0);game.acceptQuest(id);assert.equal(s.quests[id],'active');game.claimQuest(id);assert.equal(s.water,0);assert.equal(s.gold,0);s.questItems.push(id);assert(game.questReady(id));game.claimQuest(id);assert.equal(s.quests[id],'done');assert.equal(s.water,bottles);assert.equal(s.gold,gold);game.claimQuest(id);assert.equal(s.water,bottles);assert.equal(s.gold,gold);game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});game.claimQuest(id);assert.equal(game.inspect().state.water,bottles);assert.equal(game.inspect().state.gold,gold);}});

test('Friendly robot quest unlocks a gun and gold but grants no water',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;game.acceptQuest('circuit');s.kills=2;game.claimQuest('circuit');assert.equal(s.quests.circuit,'active');assert.equal(s.unlocked[3],false);const water=s.water;s.kills=3;assert(game.questReady('circuit'));game.claimQuest('circuit');assert.equal(s.quests.circuit,'done');assert.equal(s.unlocked[3],true);assert.equal(s.gold,40);assert.equal(s.water,water);game.claimQuest('circuit');assert.equal(s.gold,40);assert.equal(s.water,water);});

test('All six weapons switch, reload and survive a checkpoint',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;assert.equal(game.weapons.length,6);s.unlocked=game.weapons.map(()=>true);for(let n=0;n<game.weapons.length;n++){game.switchWeapon(n);assert.equal(s.weapon,n);s.ammo[n]=0;s.reserve[n]=3;game.reload();assert(game.inspect().reloadTimer>0);game.finishReload();assert.equal(s.ammo[n],Math.min(3,game.weapons[n].mag));assert.equal(s.reserve[n],Math.max(0,3-game.weapons[n].mag));game.configure({mode:'playing'});}game.save();game.resetRun(game.readSave());assert.equal(game.inspect().state.weapon,5);assert.deepEqual(game.inspect().state.unlocked,[true,true,true,true,true,true]);assert.equal(game.inspect().state.ammo.length,6);assert.equal(game.inspect().state.reserve.length,6);});

test('Each of the six guns fires a real damaging raycast',()=>{game.resetRun();game.configure({mode:'playing'});const {scene,camera,state:s}=game.inspect();for(const enemy of game.enemies)scene.remove(enemy.group);game.enemies.length=0;game.createEnemy(900,0,57,'heavy');const target=game.enemies[0];target.health=10000;camera.position.set(0,1.4,60);camera.rotation.set(0,0,0);s.unlocked=game.weapons.map(()=>true);for(let n=0;n<game.weapons.length;n++){game.switchWeapon(n);game.configure({mode:'playing'});const hp=target.health,ammo=s.ammo[n];game.shoot();assert.equal(s.ammo[n],ammo-1,'weapon '+n+' did not fire');assert(target.health<hp,'weapon '+n+' did not damage its target');}assert.equal(s.shots,6);});

test('Friendly faction members are never hostile guards or shootable enemy targets',()=>{assert(game.allies.length>0);for(const ally of game.allies){assert(!game.enemies.includes(ally));assert(!game.enemies.some(e=>e.group===ally.group));ally.group.traverse(mesh=>{assert(!mesh.userData.enemy,'friendly mesh has hostile target metadata');});}});

test('Building and switching all six guns never changes world material depth testing',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.unlocked=game.weapons.map(()=>true);assert.equal(game.mats.dark.depthTest,true,'the initial gun corrupted shared world materials');for(let n=0;n<game.weapons.length;n++){game.switchWeapon(n);assert.equal(game.mats.dark.depthTest,true,'weapon '+n+' disabled world depth testing');assert.equal(game.mats.dark.depthWrite,true,'weapon '+n+' disabled world depth writing');}game.switchWeapon(0);assert.equal(game.mats.dark.depthTest,true);});

test('Emergency pump water requires the completed quest, thirst, empty bottles and cooldown',()=>{game.resetRun();game.configure({mode:'playing'});let s=game.inspect().state;s.hydration=40;s.water=0;s.elapsed=120;s.pumpRefillAt=0;assert.equal(game.claimPumpWater(),false,'pump was available before its quest');s.quests.pump='active';assert.equal(game.claimPumpWater(),false);s.quests.pump='done';s.water=1;assert.equal(game.claimPumpWater(),false,'refill was farmed while carrying water');s.water=0;s.hydration=40.01;assert.equal(game.claimPumpWater(),false,'refill ignored hydration threshold');s.hydration=40;s.elapsed=119.99;assert.equal(game.claimPumpWater(),false,'refill ignored cooldown');s.elapsed=120;assert.equal(game.claimPumpWater(),true);assert.equal(s.water,2);assert.equal(s.hydration,40);assert.equal(s.pumpRefillAt,120);assert.equal(game.claimPumpWater(),false);assert.equal(s.water,2);s.water=0;s.elapsed=121;assert.equal(game.claimPumpWater(),false);game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});s=game.inspect().state;assert.equal(s.pumpRefillAt,120);assert.equal(game.claimPumpWater(),false,'reload reset the water cooldown');s.elapsed=239.99;assert.equal(game.claimPumpWater(),false);s.elapsed=240;assert.equal(game.claimPumpWater(),true);assert.equal(s.water,2);assert.equal(s.pumpRefillAt,240);});

test('Greenline spends gold correctly, refuses invalid purchases, and never grants water',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.water=1;s.hydration=37;s.health=55;s.armor=5;s.armorLevel=1;s.reserve=game.weapons.map(()=>0);for(const kind of ['ammo','repair','lmg','water','invalid']){assert.equal(game.buyFromGreenline(kind),false);assert.equal(s.gold,0);assert.equal(s.water,1);assert.equal(s.hydration,37);}assert.equal(s.health,55);assert.equal(s.unlocked[5],false);s.gold=20;assert.equal(game.buyFromGreenline('ammo'),true);assert.equal(s.gold,0);assert.equal(s.reserve[0],Math.ceil(game.weapons[0].reserve*.5));assert.equal(s.reserve[5],0,'ammo was supplied for a locked gun');assert.equal(s.water,1);assert.equal(s.hydration,37);s.gold=25;assert.equal(game.buyFromGreenline('repair'),true);assert.equal(s.gold,0);assert.equal(s.health,100);assert.equal(s.armor,65);assert.equal(s.water,1);assert.equal(s.hydration,37);s.gold=90;assert.equal(game.buyFromGreenline('lmg'),true);assert.equal(s.gold,0);assert.equal(s.unlocked[5],true);assert.equal(game.readSave().unlocked[5],true);assert.equal(s.water,1);assert.equal(s.hydration,37);s.gold=90;assert.equal(game.buyFromGreenline('lmg'),false,'owned LMG could be purchased twice');assert.equal(s.gold,90);assert.equal(game.buyFromGreenline('water'),false);assert.equal(s.water,1);assert.equal(s.hydration,37);});

test('An allied Greenline robot attacks visible hostiles without granting water',()=>{game.resetRun();game.configure({mode:'playing'});const {scene,state:s}=game.inspect();for(const enemy of game.enemies)scene.remove(enemy.group);game.enemies.length=0;const robot=game.allies.find(a=>a.robot);assert(robot);game.createEnemy(902,robot.x,robot.z-8,'walker');const enemy=game.enemies[0];assert(game.lineClear(robot.x,robot.z,enemy.x,enemy.z),'test target is obstructed');const hp=enemy.health,water=s.water,hydration=s.hydration,health=s.health;game.updateAllies(.1);assert.equal(enemy.health,hp,'robot attacked before the alliance was earned');s.reputation=1;game.updateAllies(.1);assert(enemy.health<hp);const after=enemy.health;game.updateAllies(.1);assert.equal(enemy.health,after,'support fire ignored its cooldown');enemy.x=31;enemy.z=58;enemy.group.position.set(31,0,58);assert(!game.lineClear(robot.x,robot.z,enemy.x,enemy.z),'cover fixture is not obstructed');game.updateAllies(3);assert.equal(enemy.health,after,'support fire shot through a building');assert.equal(s.water,water);assert.equal(s.hydration,hydration);assert.equal(s.health,health);});

test('The expanded city has open former borders and both settlements have routes',()=>{game.resetRun();assert.equal(game.EXPANSION_LIMIT,176);assert(game.worldBuildings.length>=8);assert.equal(game.settlements.length,2);assert(game.isClear(179,0),'former city boundary must be open');assert(game.isClear(0,-177),'north wilderness gate should be open');for(const [a,b] of [[{x:-84,z:20,y:0},{x:-100,z:20,y:0}],[{x:84,z:-28,y:0},{x:98,z:-28,y:0}],[{x:20,z:84,y:0},{x:20,z:100,y:0}]]){placeAt(a);walkTo(b);assert(distance2(game.player,b)<.45,'a former perimeter still blocks passage');}for(const place of game.settlements)assert(game.findPath(0,65,place.x,place.z).length>0,place.name+' is isolated');});

test('Every new building has a real passable door, hollow interior and solid back wall',()=>{game.resetRun();for(const b of game.worldBuildings.filter(b=>!b.id.startsWith('wild-house-'))){const {outside,threshold,inside,normal}=b.door;assert(game.isClear(b.interior.x,b.interior.z,.38,b.floorY),b.id+' interior is not hollow');placeAt(outside);walkTo(threshold);assert(distance2(game.player,threshold)<.45,b.id+' doorway threshold blocked');walkTo(inside);assert(distance2(game.player,inside)<.45,b.id+' doorway enters a solid block');walkTo(b.interior);assert(distance2(game.player,b.interior)<.45,b.id+' central aisle blocked');assert(near(game.player.y-1.72,b.floorY,.13),b.id+' floor support is wrong');const half=normal.x?b.w/2:b.d/2;const back={x:b.x-normal.x*(half+2),z:b.z-normal.z*(half+2),y:0};const through={x:b.x-normal.x*(half-2),z:b.z-normal.z*(half-2),y:b.floorY};placeAt(back);walkTo(through);assert(distance2(game.player,through)>1,b.id+' rear wall can be walked through');}});

test('Navigation paths have radius-safe traversable edges',()=>{game.resetRun();for(const target of game.settlements){const path=game.findPath(0,65,target.x,target.z);assert(path.length>0);for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],steps=Math.ceil(distance2(a,b)/.25);for(let j=0;j<=steps;j++){const t=j/steps;assert(game.isClear(a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t,.55,0),'navigation crosses a wall between adjacent cells');}}}});

test('Ground floors and roofs support the player without teleporting between levels',()=>{game.resetRun();const b=game.worldBuildings.find(b=>b.id==='east_relay')||game.worldBuildings[0];const p=b.interior;assert(near(game.supportAt(p.x,p.z,b.floorY+.01),b.floorY));assert(near(game.supportAt(p.x,p.z,b.roofY+.01),b.roofY));placeAt(p);for(let i=0;i<10;i++)game.updateVertical(.05);assert(near(game.player.y-1.72,b.floorY,.01),'street-level player snapped onto roof');placeAt({...p,y:b.roofY+2});for(let i=0;i<80;i++)game.updateVertical(.05);assert(near(game.player.y-1.72,b.roofY,.01),'falling player tunneled through roof');assert.equal(game.inspect().state.health,100);});

test('A jump cannot pass upward through a ceiling slab',()=>{game.resetRun();const b=game.worldBuildings.find(b=>b.id==='riverside_clinic');placeAt(b.interior);game.configure({velocityY:18});let highest=-Infinity;for(let i=0;i<90;i++){game.updateVertical(.02);highest=Math.max(highest,game.player.y);}assert(highest<=b.roofY-.16,'head crossed the roof slab while jumping');assert(game.player.y<b.roofY,'player reached the roof through its underside');});

test('All climb routes enforce skills and hydration, then safely reach and leave their platforms',()=>{for(const route of game.climbRoutes){game.resetRun();placeAt(route.bottomPoint);assert.equal(game.beginClimb(route),false,route.id+' climbed without its skill');const s=game.inspect().state;s.skills=['survivor','climb','mantle'];s.hydration=14;assert.equal(game.beginClimb(route),false,route.id+' allowed dehydrated climbing');s.hydration=100;assert(game.isClear(route.topPoint.x,route.topPoint.z,.38,route.topPoint.y),route.id+' top landing obstructed');assert(near(game.supportAt(route.topPoint.x,route.topPoint.z,route.topPoint.y+.01),route.topPoint.y,.02),route.id+' top landing has no support');assert.equal(game.beginClimb(route),true);finishClimb();assert(distance2(game.player,route.topPoint)<.02);assert(near(game.player.y-1.72,route.top,.02));game.updateVertical(.05);assert(near(game.player.y-1.72,route.top,.02),'completed climb falls through its landing');assert.equal(game.beginClimb(route,true),true);finishClimb();assert(distance2(game.player,route.bottomPoint)<.02);assert(near(game.player.y-1.72,route.bottom,.02));assert.equal(s.health,100,'safe climb caused fall damage');}});

test('Rooftop saves retain height, and saved falling positions continue to fall',()=>{game.resetRun();const route=game.climbRoutes.find(r=>r.id==='relay_roof')||game.climbRoutes[0];placeAt(route.topPoint);game.save();game.resetRun(game.readSave());assert(near(game.player.y-1.72,route.top,.01),'rooftop save restored at street level');game.updateVertical(.05);assert(near(game.player.y-1.72,route.top,.01));placeAt({...route.topPoint,y:route.top+2});game.save();game.resetRun(game.readSave());const start=game.player.y;game.updateVertical(.1);assert(game.player.y<start,'restored airborne save is suspended in air');for(let i=0;i<80;i++)game.updateVertical(.05);assert(near(game.player.y-1.72,route.top,.01));});

test('Saving during ascent or descent restores the safe route anchor',()=>{const route=game.climbRoutes.find(r=>r.id==='relay_roof')||game.climbRoutes[0];for(const descending of [false,true]){game.resetRun();game.inspect().state.skills=['survivor','climb','mantle'];placeAt(descending?route.topPoint:route.bottomPoint);const anchor={...game.player};assert(game.beginClimb(route,descending));game.updateClimb(game.inspect().climbState.duration*.5);assert(game.inspect().climbState,'fixture did not stop in mid-climb');assert(Math.abs(game.player.y-anchor.y)>.5);game.save();const saved=game.readSave();assert(near(saved.position.x,anchor.x));assert(near(saved.position.z,anchor.z));assert(near(saved.position.y,anchor.y),'midair ladder position was saved instead of safe anchor');game.resetRun(saved);assert.equal(game.inspect().climbState,null);assert(distance2(game.player,anchor)<.01);assert(near(game.player.y,anchor.y,.01));game.updateVertical(.05);assert(near(game.player.y,anchor.y,.01),'restored climb anchor has no support');assert.equal(game.inspect().state.health,100);}});

test('Rooftop quest items cannot be collected from inside the floor below',()=>{game.resetRun();const item=game.interactables.find(i=>i.type==='questItem'&&i.id==='relay');assert(item&&item.y>3);placeAt({x:item.x,z:item.z,y:.08});game.updateInteract();assert.notEqual(game.inspect().interactTarget,item,'rooftop module is reachable through ceiling');game.interact();assert(!game.inspect().state.questItems.includes('relay'));placeAt({x:item.x,z:item.z,y:item.y});game.updateInteract();assert.equal(game.inspect().interactTarget,item);game.interact();assert(game.inspect().state.questItems.includes('relay'));});

test('Interior loot is reachable at its own height and remains exhausted after reload',()=>{game.resetRun();const item=game.interactables.find(i=>i.type==='interiorLoot'&&(i.y||0)<.5);placeAt(item);game.updateInteract();assert.equal(game.inspect().interactTarget,item);const s=game.inspect().state,water=s.water;assert.equal(game.lootInterior(item),true);assert(s.opened.includes(item.id));assert.equal(s.water,water+(item.water||0));const after={water:s.water,scrap:s.scrap,gold:s.gold,xp:s.xp};assert.equal(game.lootInterior(item),false);assert.deepEqual({water:s.water,scrap:s.scrap,gold:s.gold,xp:s.xp},after);game.save();game.resetRun(game.readSave());placeAt(item);game.updateInteract();assert.notEqual(game.inspect().interactTarget,item);assert.equal(game.lootInterior(item),false);assert.equal(game.inspect().state.water,after.water);});

test('Skill purchases require a connected affordable node and never spend twice',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;assert.equal(game.SKILL_NODES.length,18);assert.deepEqual(s.skills,['survivor']);assert.equal(s.skillPoints,2);for(const id of ['unknown','survivor','reload','climber2']){assert.equal(game.unlockPerk(id),false);assert.equal(s.skillPoints,2);}assert(game.unlockPerk('climb'));assert.equal(s.skillPoints,1);assert(game.perkBonuses().canClimb);assert.equal(game.unlockPerk('climb'),false);assert.equal(s.skillPoints,1);assert(game.unlockPerk('mantle'));assert.equal(s.skillPoints,0);assert(game.perkBonuses().canMantle);assert.equal(game.unlockPerk('marksman'),false);assert.equal(s.skillPoints,0);game.save();game.resetRun(game.readSave());assert.deepEqual(game.inspect().state.skills,['survivor','climb','mantle']);assert.equal(game.inspect().state.skillPoints,0);assert.equal(game.canUnlockSkill('reload',['survivor','marksman'],1),true);assert.equal(game.canUnlockSkill('reload',['survivor'],10),false);});

test('XP awards cross multiple escalating thresholds without losing the remainder',()=>{game.resetRun();const s=game.inspect().state;game.awardXP(99);assert.equal(s.level,1);assert.equal(s.xp,99);game.awardXP(1);assert.equal(s.level,2);assert.equal(s.xp,0);assert.equal(s.skillPoints,3);game.awardXP(310);assert.equal(s.level,4);assert.equal(s.xp,5);assert.equal(s.skillPoints,5);assert.equal(game.nextLevelXP(),205);game.awardXP(-50);assert.equal(s.xp,5);game.save();game.resetRun(game.readSave());assert.equal(game.inspect().state.level,4);assert.equal(game.inspect().state.xp,5);assert.equal(game.inspect().state.skillPoints,5);});

test('Vitality and medicine affect actual healing, repairs and saved health limits',()=>{game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.skillPoints=8;assert(game.unlockPerk('vitality'));assert.equal(game.perkBonuses().maxHealth,125);assert.equal(s.health,125);s.health=110;game.save();game.resetRun(game.readSave());assert.equal(game.inspect().state.health,110,'save clipped upgraded health to100');const restored=game.inspect().state;restored.skillPoints=8;game.configure({mode:'playing'});assert(game.unlockPerk('hydration'));assert(game.unlockPerk('medic'));restored.health=20;restored.meds=1;game.heal();assert.equal(restored.health,110,'medkit bonus did not affect healing');restored.gold=25;game.buyFromGreenline('repair');assert.equal(restored.health,125,'repair did not use upgraded maximum health');});

test('Water Wise, reload and movement perks alter their actual gameplay rates once',()=>{game.resetRun();const s=game.inspect().state;game.configure({mode:'playing',keys:{}});s.skills=['survivor','vitality','hydration'];s.hydration=100;game.updateSurvival(10);assert(near(s.hydration,100-1.8*.8));s.skills=['survivor','marksman','reload'];s.ammo[0]=0;s.reserve[0]=100;game.reload();assert(near(game.inspect().reloadTimer,game.weapons[0].reload*.8));game.finishReload();s.skills=['survivor'];placeAt({x:0,z:60,y:0});game.configure({yaw:0,keys:{KeyW:true}});for(let i=0;i<20;i++)game.updatePlayer(.05);const normal=60-game.player.z;s.skills=['survivor','climb','parkour'];placeAt({x:0,z:60,y:0});game.configure({yaw:0,keys:{KeyW:true}});for(let i=0;i<20;i++)game.updatePlayer(.05);const enhanced=60-game.player.z;assert(near(enhanced/normal,1.12,.002),'move perk is only descriptive');s.skills=['survivor','climb','parkour','parkour'];assert(near(game.perkBonuses().moveRate,1.12),'duplicate skill stacked a bonus');game.configure({keys:{}});});

test('Climbing speed and fall protection perks change real traversal outcomes',()=>{const route=game.climbRoutes.find(r=>r.requires==='climb');game.resetRun();game.inspect().state.skills=['survivor','climb'];placeAt(route.bottomPoint);assert(game.beginClimb(route));const normalTime=game.inspect().climbState.duration;game.resetRun();game.inspect().state.skills=['survivor','climb','mantle','climber2'];placeAt(route.bottomPoint);assert(game.beginClimb(route));assert(near(game.inspect().climbState.duration,normalTime/1.4));finishClimb();const fallDamage=skills=>{game.resetRun();game.inspect().state.skills=skills;placeAt({x:20,z:100,y:6});for(let i=0;i<150;i++)game.updateVertical(.02);assert(near(game.player.y,1.72,.02));return 100-game.inspect().state.health;};const ordinary=fallDamage(['survivor']),protectedFall=fallDamage(['survivor','climb','parkour']);assert(ordinary>0);assert(near(protectedFall,ordinary*.75,.01));});

test('Damage and salvage perks affect combat and stored gold exactly once',()=>{game.resetRun();game.configure({mode:'playing'});const {scene,camera,state:s}=game.inspect();for(const enemy of game.enemies)scene.remove(enemy.group);game.enemies.length=0;game.createEnemy(997,0,57,'heavy');const target=game.enemies[0];target.health=10000;camera.position.set(0,1.4,60);camera.rotation.set(0,0,0);const before=target.health;game.shoot();const ordinary=before-target.health;s.skills=['survivor','marksman'];game.configure({mode:'playing'});const markedBefore=target.health;game.shoot();assert(near(markedBefore-target.health,ordinary*1.15,.001));game.resetRun();game.configure({mode:'playing'});const state=game.inspect().state;state.skills=['survivor','scavenger'];const robot=game.enemies.find(e=>e.type==='walker');game.damageEnemy(robot,999,new (game.inspect().camera.position.constructor)(robot.x,1,robot.z));const drop={...state.pendingGold.at(-1)};assert.equal(drop.gold,Math.round(14*1.2));const water=state.water;game.save();game.resetRun(game.readSave());const restored=game.inspect().state;assert.equal(restored.pendingGold.at(-1).gold,drop.gold,'loading multiplied saved loot again');game.collectRobotGold(game.pickups.find(p=>p.id===drop.id));assert.equal(restored.gold,drop.gold);assert.equal(restored.water,water);});

test('Version-two saves gain expansion fields while preserving survival and quest progress',()=>{game.resetRun();const legacy={...game.inspect().state,version:2,hydration:17,water:7,gold:120,quests:{filter:'done',pump:'active',circuit:'done'},reputation:1,supplies:['water:0'],questItems:['filter'],position:{x:0,z:65}};for(const key of ['skills','skillPoints','xp','level','visitedBuildings','settlementRefills'])delete legacy[key];const restored=game.safeRestore(legacy);assert.equal(restored.version,3);assert.equal(restored.hydration,17);assert.equal(restored.water,7);assert.equal(restored.gold,120);assert.equal(restored.quests.filter,'done');assert.equal(restored.quests.pump,'active');assert.equal(restored.reputation,1);assert.deepEqual(restored.skills,['survivor']);assert.equal(restored.skillPoints,2);assert.equal(restored.xp,0);assert.equal(restored.level,1);assert.deepEqual(restored.visitedBuildings,[]);assert.deepEqual(restored.settlementRefills,{});});

test('Each human settlement shares water repeatedly with an independent saved cooldown',()=>{game.resetRun();const s=game.inspect().state;s.water=0;s.elapsed=0;assert.equal(game.claimSettlementWater('not-a-place'),false);for(const place of game.settlements){const keeper=game.allies.find(a=>a.id===place.npcId);assert(keeper&&!keeper.robot,'settlement ration must have a human keeper');const before=s.water;assert.equal(game.claimSettlementWater(place.id),true);assert.equal(s.water,before+2);assert.equal(game.claimSettlementWater(place.id),false);}assert.equal(s.water,4);game.save();game.resetRun(game.readSave());const loaded=game.inspect().state;for(const place of game.settlements)assert.equal(game.claimSettlementWater(place.id),false,'reload reset a ration cooldown');loaded.elapsed=119.99;assert.equal(game.claimSettlementWater(game.settlements[0].id),false);loaded.elapsed=120;for(const place of game.settlements)assert.equal(game.claimSettlementWater(place.id),true);assert.equal(loaded.water,8);});

test('Medicine and rooftop relay turn-ins award their human water, gold and 80 XP only once',()=>{for(const [id,water,gold] of [['medicine',4,60],['relay',5,80]]){game.resetRun();game.configure({mode:'playing'});const s=game.inspect().state;s.water=0;s.gold=0;assert(game.acceptQuest(id));assert.equal(game.claimQuest(id),false,'quest turned in without its item');s.questItems.push(id);assert(game.questReady(id));assert.equal(game.claimQuest(id),true);assert.equal(s.quests[id],'done');assert.equal(s.water,water);assert.equal(s.gold,gold);assert.equal(s.xp,80);assert.equal(s.level,1);assert.equal(game.claimQuest(id),false);assert.equal(s.xp,80);game.save();game.resetRun(game.readSave());game.configure({mode:'playing'});const loaded=game.inspect().state;assert.equal(game.claimQuest(id),false,'reload allowed a duplicate turn-in');assert.equal(loaded.water,water);assert.equal(loaded.gold,gold);assert.equal(loaded.xp,80);}});

test('Robots aim at elevated players while solid roof slabs stop swept projectiles',()=>{game.resetRun();game.configure({mode:'playing'});let s=game.inspect().state;s.difficulty='desolate';s.health=100;s.armor=0;placeAt({x:20,z:100,y:6});game.createEnemy(991,20,110,'walker');const attacker=game.enemies.find(e=>e.id===991);game.enemyFire(attacker);assert(game.projectiles.at(-1).v.y>0,'robot fire still aims at ground height');for(let i=0;i<180&&s.health===100;i++)game.updateEffects(.01);assert(s.health<100,'elevated player is immune to visible robot fire');game.resetRun();game.configure({mode:'playing'});s=game.inspect().state;s.difficulty='desolate';s.health=100;s.armor=0;const b=game.worldBuildings.find(b=>b.id==='east_relay');placeAt({x:b.x,z:b.z,y:b.roofY});game.createEnemy(992,b.x,b.z,'walker');const below=game.enemies.find(e=>e.id===992);assert(!game.lineClear(b.x,b.z,b.x,b.z,1.45,game.player.y-.2),'roof does not block vertical visibility');game.enemyFire(below);game.updateEffects(1);assert.equal(s.health,100,'projectile damaged player after crossing a roof slab');});

test('Blocked browser storage allows play and pause reports the actual save result',()=>{const availableStorage=globalThis.localStorage;try{globalThis.localStorage={getItem(){throw new Error('Storage blocked');},setItem(){throw new Error('Storage blocked');}};assert.equal(game.readSave(),null);assert.doesNotThrow(()=>game.begin());game.closePanel();assert.equal(game.inspect().mode,'playing');assert.doesNotThrow(()=>game.updateSurvival(.1));assert.equal(game.save(),false);game.pause();assert.equal(game.inspect().mode,'paused');assert.match(element('panel').innerHTML,/SESSION ONLY/);assert.match(element('panel').innerHTML,/Browser storage is unavailable/);assert.doesNotMatch(element('panel').innerHTML,/PROGRESS SAVED|story is saved/);game.closePanel();assert.equal(game.inspect().mode,'playing');}finally{globalThis.localStorage=availableStorage;}assert.equal(game.save(),true);game.pause();assert.match(element('panel').innerHTML,/PROGRESS SAVED/);assert.match(element('panel').innerHTML,/saved on this browser/);assert.doesNotMatch(element('panel').innerHTML,/SESSION ONLY|storage is unavailable/);game.inspect().state.health=0;assert.equal(game.save(),false,'dead runs must not replace a save');});
test('Corrupt browser save does not prevent a new game',()=>{storage.set('EARTHtotaled.story.v1','{bad');assert.equal(game.readSave(),null);});

// Dispatch registered application handlers with controlled browser API results.
// These checks cover event ordering and recovery, not browser permission grants.
const flushPromises=async()=>{for(let i=0;i<5;i++)await Promise.resolve();};
await flushPromises();
game.bindInput();
function resetCapture(){game.configure({mode:'menu',keys:{}});document.pointerLockElement=null;game.unlockMouse();dispatch(document,'pointerlockchange');game.resetRun();game.configure({mode:'playing'});game.updateMouseCaptureUI();}

await testAsync('Workbench return can retry a rejected mouse lock without firing a shot',async()=>{
 const world=element('world'),request=world.requestPointerLock,exit=document.exitPointerLock;let attempts=0;
 try{
  resetCapture();document.pointerLockElement=world;dispatch(document,'pointerlockchange');
  document.exitPointerLock=()=>{document.pointerLockElement=null;dispatch(document,'pointerlockchange');};
  world.requestPointerLock=()=>{attempts++;return attempts===1?Promise.reject(new Error('Lock denied')):Promise.resolve();};
  const s=game.inspect().state;s.scrap=100;game.bench();assert.equal(game.inspect().mode,'bench');
  element('upgradeDamage').onclick();assert.equal(s.damageLevel,1);
  element('benchBack').onclick();await flushPromises();
  assert.equal(game.inspect().mode,'playing');assert.equal(attempts,1);assert.equal(game.inspect().pointerPending,false);
  assert.equal(element('captureMouse').classList.contains('hidden'),false);assert.match(element('captureMouse').textContent,/DRAG.*ARROWS/);
  const shots=s.shots,ammo=s.ammo[0];element('captureMouse').onclick();assert.equal(attempts,2,'a rejection permanently disabled capture retries');
  assert.equal(game.inspect().fireHeld,false);assert.equal(s.shots,shots);assert.equal(s.ammo[0],ammo);
  document.pointerLockElement=world;dispatch(document,'pointerlockchange');await flushPromises();
  assert.equal(game.inspect().mode,'playing');assert.equal(element('captureMouse').classList.contains('hidden'),true);
 }finally{world.requestPointerLock=request;document.exitPointerLock=exit;resetCapture();await flushPromises();}
});

await testAsync('Delayed workbench unlock recaptures without pausing but external lock loss pauses',async()=>{
 const world=element('world'),request=world.requestPointerLock,exit=document.exitPointerLock;let attempts=0,exits=0;
 try{
  resetCapture();document.pointerLockElement=world;dispatch(document,'pointerlockchange');
  document.exitPointerLock=()=>{exits++;};world.requestPointerLock=()=>{attempts++;return Promise.resolve();};
  game.bench();assert.equal(exits,1);element('benchBack').onclick();
  assert.equal(game.inspect().mode,'playing');assert.equal(attempts,0,'capture must wait for the intentional unlock');
  document.pointerLockElement=null;dispatch(document,'pointerlockchange');
  assert.equal(game.inspect().mode,'playing','delayed intentional unlock reopened the pause panel');assert.equal(attempts,1);
  document.pointerLockElement=world;dispatch(document,'pointerlockchange');await flushPromises();
  dispatch(world,'mousedown',{button:0});dispatch(document,'keydown',{code:'KeyW',repeat:false});
  assert.equal(game.inspect().fireHeld,true);assert.equal(game.inspect().keys.KeyW,true);
  document.pointerLockElement=null;dispatch(document,'pointerlockchange');
  assert.equal(game.inspect().mode,'paused');assert.equal(game.inspect().fireHeld,false);assert.deepEqual(game.inspect().keys,{});
  assert.equal(element('captureMouse').classList.contains('hidden'),true);
 }finally{world.requestPointerLock=request;document.exitPointerLock=exit;resetCapture();await flushPromises();}
});

await testAsync('Event-only pointer lock failures preserve drag look and a later canvas retry',async()=>{
 const world=element('world'),request=world.requestPointerLock;let attempts=0;
 try{
  resetCapture();world.requestPointerLock=()=>{attempts++;};game.lockMouse();
  assert.equal(game.inspect().pointerPending,true);dispatch(document,'pointerlockerror');
  assert.equal(game.inspect().pointerPending,false);assert.equal(element('captureMouse').classList.contains('hidden'),false);
  const yaw=game.inspect().yaw;dispatch(document,'mousemove',{buttons:2,movementX:10,movementY:0});assert(game.inspect().yaw<yaw,'drag look was disabled by capture failure');
  dispatch(world,'mousedown',{button:0});assert.equal(attempts,2);
  document.pointerLockElement=world;dispatch(document,'pointerlockchange');dispatch(document,'mouseup',{button:0});
  assert.equal(game.inspect().mode,'playing');assert.equal(game.inspect().fireHeld,false);assert.equal(element('captureMouse').classList.contains('hidden'),true);
 }finally{world.requestPointerLock=request;resetCapture();await flushPromises();}
});

await testAsync('Browser capture requests raw movement and falls back only when unsupported',async()=>{
 const world=element('world'),original=world.requestPointerLock;
 try{
  resetCapture();let calls=[];world.requestPointerLock=options=>{calls.push(options);document.pointerLockElement=world;dispatch(document,'pointerlockchange');return Promise.resolve();};
  assert.equal(game.lockMouse(),true);await flushPromises();assert.deepEqual(calls,[{unadjustedMovement:true}]);assert.equal(element('captureMouse').classList.contains('hidden'),true);
  for(const synchronous of [false,true])for(const name of ['NotSupportedError','TypeError']){
   resetCapture();calls=[];world.requestPointerLock=options=>{calls.push(options);if(options){const error=Object.assign(new Error('Raw input unavailable'),{name});if(synchronous)throw error;return Promise.reject(error);}document.pointerLockElement=world;dispatch(document,'pointerlockchange');return Promise.resolve();};
   assert.equal(game.lockMouse(),true);await flushPromises();assert.deepEqual(calls,[{unadjustedMovement:true},undefined]);assert.equal(game.inspect().pointerPending,false);assert.equal(game.inspect().mode,'playing');assert.equal(element('captureMouse').classList.contains('hidden'),true);
  }
  resetCapture();calls=[];world.requestPointerLock=options=>{calls.push(options);return Promise.reject(Object.assign(new Error('Denied'),{name:'NotAllowedError'}));};game.lockMouse();await flushPromises();assert.equal(calls.length,1,'permission denial retried automatically');assert.equal(game.inspect().pointerPending,false);assert.equal(element('captureMouse').classList.contains('hidden'),false);
 }finally{world.requestPointerLock=original;resetCapture();await flushPromises();}
});

await testAsync('A late unsupported-raw response cannot recapture the mouse after opening a menu',async()=>{
 const world=element('world'),original=world.requestPointerLock;let reject,calls=0;
 try{
  resetCapture();world.requestPointerLock=()=>{calls++;return new Promise((_resolve,fail)=>reject=fail);};game.lockMouse();game.bench();reject(Object.assign(new Error('Unsupported raw input'),{name:'NotSupportedError'}));await flushPromises();assert.equal(calls,1);assert.equal(game.inspect().mode,'bench');assert.equal(game.inspect().pointerPending,false);
 }finally{world.requestPointerLock=original;resetCapture();await flushPromises();}
});

await testAsync('Fullscreen controls and Alt Enter follow browser events and recover from denial',async()=>{
 const root=document.documentElement,request=root.requestFullscreen,exit=document.exitFullscreen;let requests=0,exits=0;
 const checkLabels=active=>{for(const id of ['fullscreenMenu','fullscreenHUD','fullscreenPause']){assert.equal(element(id).getAttribute('aria-pressed'),String(active));assert.equal(element(id).getAttribute('aria-label'),active?'Exit fullscreen':'Enter fullscreen');assert.equal(element(id).textContent,active?'⛶ EXIT FULLSCREEN':'⛶ FULLSCREEN');}};
 try{
  resetCapture();game.configure({mode:'menu'});document.fullscreenElement=null;dispatch(document,'fullscreenchange');checkLabels(false);
  root.requestFullscreen=async()=>{requests++;document.fullscreenElement=root;dispatch(document,'fullscreenchange');};
  document.exitFullscreen=async()=>{exits++;document.fullscreenElement=null;dispatch(document,'fullscreenchange');};
  assert.equal(await element('fullscreenMenu').onclick(),true);assert.equal(requests,1);checkLabels(true);
  assert.equal(await element('fullscreenHUD').onclick(),true);assert.equal(exits,1);checkLabels(false);
  game.configure({mode:'playing'});game.pause();assert.equal(await element('fullscreenPause').onclick(),true);assert.equal(requests,2);assert.equal(game.inspect().mode,'paused');checkLabels(true);
  let prevented=false;dispatch(document,'keydown',{code:'Enter',altKey:true,repeat:false,preventDefault(){prevented=true;}});await flushPromises();
  assert.equal(prevented,true);assert.equal(exits,2);assert.equal(game.inspect().mode,'paused');checkLabels(false);
  root.requestFullscreen=()=>Promise.reject(new Error('Fullscreen denied'));assert.equal(await game.toggleFullscreen(),false);
  assert.equal(game.inspect().mode,'paused');assert.equal(document.fullscreenElement,null);checkLabels(false);
 }finally{root.requestFullscreen=request;document.exitFullscreen=exit;document.fullscreenElement=null;dispatch(document,'fullscreenchange');resetCapture();await flushPromises();}
});

test('Desktop mouse capture uses native input and releases cleanly for menus and focus loss',()=>{
 const original=document.getElementById('world').requestPointerLock;let captures=0,releases=0,browserRequests=0;
 window.earthDesktop={captured:false,capture(){captures++;},release(){releases++;}};
 document.getElementById('world').requestPointerLock=()=>{browserRequests++;throw Error('browser capture must not be used by desktop');};
 try{
  game.resetRun();game.configure({mode:'playing',yaw:0,pitch:0,keys:{KeyW:true}});game.unlockMouse();
  assert.equal(game.lockMouse(),true);assert.equal(captures,1);assert(game.inspect().pointerPending);
  window.earthDesktop.captured=true;game.handleDesktopCapture();assert.equal(game.inspect().pointerPending,false);assert(document.getElementById('captureMouse').classList.contains('hidden'));
  game.handleDesktopMove({detail:{dx:100,dy:50}});assert(near(game.inspect().yaw,-.21));assert(near(game.inspect().pitch,-.105));
  const before=game.inspect().yaw;dispatch(document,'mousemove',{buttons:1,movementX:100,movementY:0});assert.equal(game.inspect().yaw,before,'legacy mouse move counted native motion twice');
  game.bench();assert(releases>0);window.earthDesktop.captured=false;game.handleDesktopCapture();assert.equal(game.inspect().mode,'bench');
  game.handleDesktopMove({detail:{dx:100,dy:10}});assert.equal(game.inspect().yaw,before,'menu mouse motion rotated the camera');
  game.closePanel();assert.equal(game.inspect().mode,'playing');assert.equal(captures,2);window.earthDesktop.captured=true;game.handleDesktopCapture();
  window.earthDesktop.captured=false;game.handleDesktopCapture();assert.equal(game.inspect().mode,'paused','focus loss did not pause');assert.deepEqual(game.inspect().keys,{});
  game.closePanel();window.earthDesktop.captured=false;game.handleDesktopCapture();assert.equal(game.inspect().pointerPending,false);assert(!document.getElementById('captureMouse').classList.contains('hidden'),'denied native capture cannot be retried');
  const count=captures;game.lockMouse();assert.equal(captures,count+1);assert.equal(browserRequests,0);
 }finally{game.unlockMouse();delete window.earthDesktop;document.getElementById('world').requestPointerLock=original;game.configure({mode:'playing',keys:{}});}
});

